export function initAlbumView(){const page=document.querySelector('.album-layout'),button=document.getElementById('album-view-toggle');if(!page||!button)return;let view='grid';try{view=localStorage.getItem('milkroad-album-view')==='list'?'list':'grid';}catch{}const paint=()=>{page.dataset.view=view;const icon=document.createElement('img');icon.src=new URL('./album-data/ui/'+(view==='grid'?'view-list.png':'view-grid.png'),import.meta.url);icon.alt='';icon.className=view==='grid'?'toggle-list-icon':'toggle-grid-icon';button.replaceChildren(icon);button.title=view==='grid'?'List View':'Grid View';button.setAttribute('aria-label',view==='grid'?'Switch to list view':'Switch to grid view');button.setAttribute('aria-pressed',String(view==='list'));};button.onclick=()=>{view=view==='grid'?'list':'grid';try{localStorage.setItem('milkroad-album-view',view);}catch{}paint();};paint();}
